// Запросы к API Supabase от имени вошедшего пользователя — с его же токеном из запроса приложения (как QA 28–29.10).
// Адрес API, apikey и Authorization берутся из настоящего запроса страницы, ничего не хранится в коде.
import { expect, type Page, type APIResponse } from '@playwright/test';

export type Api = { page: Page; base: string; apikey: string; auth: string; userId: string };

// Открыть страницу и дождаться запроса приложения к /rest/v1 с токеном пользователя (не анонимным ключом).
export async function captureApi(page: Page, url = '/discover'): Promise<Api> {
  const wait = page.waitForRequest((r) => {
    const h = r.headers();
    return r.url().includes('/rest/v1/') && !!h['apikey'] && !!h['authorization'] && h['authorization'] !== `Bearer ${h['apikey']}`;
  });
  await page.goto(url);
  const req = await wait;
  const h = await req.allHeaders();
  const base = req.url().split('/rest/v1/')[0];
  const auth = h['authorization'];
  const payload = JSON.parse(Buffer.from(auth.split(' ')[1].split('.')[1], 'base64url').toString('utf8'));
  expect(payload.sub, 'id пользователя в токене').toBeTruthy();
  return { page, base, apikey: h['apikey'], auth, userId: String(payload.sub) };
}

// Гость: тот же адрес и публичный apikey, без Authorization.
export const asGuest = (api: Api, page: Page): Api => ({ ...api, page, auth: '', userId: '' });

function headers(api: Api, extra: Record<string, string> = {}) {
  const h: Record<string, string> = { apikey: api.apikey, 'Content-Type': 'application/json', ...extra };
  if (api.auth) h['Authorization'] = api.auth;
  return h;
}

export const rpc = (api: Api, fn: string, data: unknown = {}): Promise<APIResponse> =>
  api.page.request.post(`${api.base}/rest/v1/rpc/${fn}`, { headers: headers(api), data, failOnStatusCode: false });

export const restGet = (api: Api, pathAndQuery: string): Promise<APIResponse> =>
  api.page.request.get(`${api.base}/rest/v1/${pathAndQuery}`, { headers: headers(api), failOnStatusCode: false });

export const restPost = (api: Api, table: string, data: unknown): Promise<APIResponse> =>
  api.page.request.post(`${api.base}/rest/v1/${table}`, {
    headers: headers(api, { Prefer: 'return=representation' }),
    data,
    failOnStatusCode: false,
  });

export const restDelete = (api: Api, pathAndQuery: string): Promise<APIResponse> =>
  api.page.request.delete(`${api.base}/rest/v1/${pathAndQuery}`, { headers: headers(api, { Prefer: 'return=representation' }), failOnStatusCode: false });

export type Row = Record<string, unknown>;

// Мэтчи пользователя (rpc/my_matches). Строка мэтча с партнёром — та, где встречается его id.
export async function myMatches(api: Api): Promise<Row[]> {
  const res = await rpc(api, 'my_matches', {});
  expect(res.status(), `my_matches: ${await res.text()}`).toBe(200);
  const body = await res.json();
  return Array.isArray(body) ? body : [];
}
export const matchIdOf = (r: Row) => String(r.match_id ?? r.id ?? '');
export const rowsWith = (rows: Row[], partnerId: string) => rows.filter((r) => JSON.stringify(r).includes(partnerId));

// Полный id мэтча по префиксу (2651ee46 и т. п.): сначала my_matches, затем таблица matches (видна участнику по RLS).
export async function fullMatchId(api: Api, prefix: string): Promise<string> {
  const fromRpc = (await myMatches(api)).map(matchIdOf).find((id) => id.startsWith(prefix));
  if (fromRpc) return fromRpc;
  const res = await restGet(api, 'matches?select=id');
  const rows: Row[] = res.ok() ? await res.json() : [];
  const id = rows.map((r) => String(r.id)).find((x) => x.startsWith(prefix));
  if (!id) throw new Error(`Не найден мэтч ${prefix}… у пользователя ${api.userId} — проверь тестовые данные (.qa/session.json test_data)`);
  return id;
}

// Колонка текста сообщения: из существующих сообщений мэтча (там есть «QA-AUTO …»), иначе типовые имена.
export async function messageTextKey(api: Api, matchId: string): Promise<string> {
  const res = await restGet(api, `messages?match_id=eq.${matchId}&limit=50`);
  const rows: Row[] = res.ok() ? await res.json() : [];
  for (const r of rows) {
    const k = Object.keys(r).find((key) => typeof r[key] === 'string' && String(r[key]).startsWith('QA-AUTO'));
    if (k) return k;
  }
  const keys = rows[0] ? Object.keys(rows[0]) : [];
  return ['body', 'content', 'text', 'message'].find((k) => keys.includes(k)) ?? 'body';
}

export const qaText = (tag: string) => `QA-AUTO ${tag} ${new Date().toISOString()}`;
